diff --git a/apps/web/src/app/brand-qualification/brand-qualification.module.css b/apps/web/src/app/brand-qualification/brand-qualification.module.css
new file mode 100644
index 0000000..6c2a55a
--- /dev/null
+++ b/apps/web/src/app/brand-qualification/brand-qualification.module.css
@@ -0,0 +1,432 @@
+.page {
+  --cw-navy: #071a2d;
+  --cw-aqua: #16dde3;
+  --cw-ink: #10263a;
+  --cw-muted: #637482;
+  --cw-line: #d8e1e7;
+  --cw-bg: #f4f8fb;
+  min-width: 0;
+  min-height: 100vh;
+  max-width: none;
+  margin: 0;
+  padding: clamp(0.75rem, 2vw, 2rem);
+  background: var(--cw-bg);
+  color: var(--cw-ink);
+}
+
+.header {
+  display: flex;
+  max-width: 92rem;
+  margin: 0 auto 1rem;
+  padding: clamp(1rem, 3vw, 2rem);
+  gap: 1rem;
+  align-items: flex-start;
+  justify-content: space-between;
+  border-radius: 1rem;
+  background: var(--cw-navy);
+  color: white;
+}
+
+.header h1 {
+  max-width: 52rem;
+  margin: 0.15rem 0 0.45rem;
+  font-size: clamp(1.55rem, 4vw, 2.8rem);
+  line-height: 1.08;
+}
+
+.eyebrow {
+  margin: 0;
+  color: var(--cw-aqua);
+  font-size: 0.72rem;
+  font-weight: 800;
+  letter-spacing: 0.11em;
+  text-transform: uppercase;
+}
+
+.lede {
+  max-width: 55rem;
+  margin: 0;
+  color: #c9d8e2;
+}
+
+.pending {
+  flex: 0 0 auto;
+  padding: 0.55rem 0.75rem;
+  border: 1px solid #47657b;
+  border-radius: 999px;
+  color: #e3edf2;
+  font-size: 0.68rem;
+  font-weight: 800;
+  letter-spacing: 0.06em;
+}
+
+.grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  max-width: 92rem;
+  margin: 0 auto;
+  gap: 1rem;
+}
+
+.card,
+.checklist {
+  min-width: 0;
+  overflow: hidden;
+  border: 1px solid var(--cw-line);
+  border-radius: 1rem;
+  background: white;
+  box-shadow: 0 0.3rem 1.3rem rgb(7 26 45 / 5%);
+}
+
+.cardHead {
+  display: flex;
+  min-width: 0;
+  padding: 0.8rem 1rem;
+  gap: 0.8rem;
+  align-items: center;
+  justify-content: space-between;
+  border-bottom: 1px solid var(--cw-line);
+}
+
+.cardHead h2 {
+  margin: 0;
+  font-size: clamp(0.95rem, 2vw, 1.08rem);
+}
+
+.cardHead span {
+  color: var(--cw-muted);
+  font-size: 0.72rem;
+  font-weight: 700;
+  text-align: right;
+}
+
+.lockupStageLight,
+.lockupStageDark {
+  display: grid;
+  width: 100%;
+  aspect-ratio: 16 / 6;
+  place-items: center;
+  padding: clamp(0.8rem, 3vw, 2rem);
+}
+
+.lockupStageLight {
+  background: white;
+}
+
+.lockupStageDark {
+  background: var(--cw-navy);
+}
+
+.lockup {
+  display: block;
+  width: 100%;
+  max-width: 50rem;
+  height: 100%;
+  max-height: 16rem;
+  object-fit: contain;
+}
+
+.markGrid,
+.iconGrid,
+.appGrid {
+  display: grid;
+  padding: 1rem;
+  gap: 0.9rem;
+}
+
+.markGrid {
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+}
+
+.iconGrid {
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+}
+
+.appGrid {
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+}
+
+.card figure {
+  min-width: 0;
+  margin: 0;
+  text-align: center;
+}
+
+.card figure figcaption {
+  margin-top: 0.45rem;
+  color: var(--cw-muted);
+  font-size: 0.75rem;
+}
+
+.squareLight,
+.squareDark {
+  display: grid;
+  aspect-ratio: 1;
+  place-items: center;
+  border-radius: 0.75rem;
+}
+
+.squareLight {
+  background: #f9fbfc;
+}
+
+.squareDark {
+  background: var(--cw-navy);
+}
+
+.squareLight img,
+.squareDark img {
+  display: block;
+  width: 78%;
+  height: 78%;
+  object-fit: contain;
+}
+
+.wordmarkLight,
+.wordmarkDark {
+  display: grid;
+  width: 100%;
+  min-height: 8rem;
+  place-items: center;
+  padding: 1.2rem;
+}
+
+.wordmarkDark {
+  background: var(--cw-navy);
+}
+
+.wordmarkLight img,
+.wordmarkDark img {
+  display: block;
+  width: min(100%, 42rem);
+  max-height: 7rem;
+  object-fit: contain;
+}
+
+.note {
+  margin: 0;
+  padding: 0.8rem 1rem;
+  color: var(--cw-muted);
+  font-size: 0.8rem;
+}
+
+.microList {
+  display: grid;
+  padding: 0 1rem 1rem;
+  gap: 0.8rem;
+}
+
+.microRow {
+  display: grid;
+  grid-template-columns: 3.8rem 4rem minmax(0, 1fr);
+  min-height: 7rem;
+  gap: 0.8rem;
+  align-items: center;
+}
+
+.nativeBox,
+.zoomBox {
+  display: grid;
+  place-items: center;
+  border: 1px dashed #bcc9d2;
+  border-radius: 0.6rem;
+  background: #fbfdfe;
+}
+
+.nativeBox {
+  width: 4rem;
+  height: 4rem;
+}
+
+.zoomBox {
+  width: 7rem;
+  height: 7rem;
+}
+
+.zoomBox img {
+  width: 6rem;
+  height: 6rem;
+  image-rendering: pixelated;
+  object-fit: contain;
+}
+
+.faviconCell {
+  display: grid;
+  min-height: 5rem;
+  place-items: center;
+}
+
+.appGrid img {
+  display: block;
+  width: 100%;
+  max-width: 8rem;
+  aspect-ratio: 1;
+  margin: 0 auto;
+  border-radius: 22%;
+  object-fit: contain;
+  box-shadow: 0 0.45rem 1rem rgb(7 26 45 / 16%);
+}
+
+.maskStage {
+  display: grid;
+  min-height: 18rem;
+  place-items: center;
+  padding: 1.25rem;
+  background:
+    linear-gradient(45deg, #eef4f7 25%, transparent 25%) 0 0 / 1rem 1rem,
+    linear-gradient(-45deg, #eef4f7 25%, transparent 25%) 0 0 / 1rem 1rem,
+    linear-gradient(45deg, transparent 75%, #eef4f7 75%) 0 0 / 1rem 1rem,
+    linear-gradient(-45deg, transparent 75%, #eef4f7 75%) 0 0 / 1rem 1rem;
+}
+
+.safeCircle {
+  width: min(15rem, 72vw);
+  aspect-ratio: 1;
+  overflow: hidden;
+  border: 2px dashed #f19b38;
+  border-radius: 50%;
+}
+
+.safeCircle img {
+  display: block;
+  width: 100%;
+  height: 100%;
+  object-fit: contain;
+}
+
+.wide {
+  grid-column: 1 / -1;
+}
+
+.socialGrid {
+  display: grid;
+  grid-template-columns: minmax(0, 1.3fr) minmax(0, 0.7fr);
+  padding: 1rem;
+  gap: 1rem;
+  align-items: start;
+}
+
+.mediaFrameWide,
+.mediaFrameSquare {
+  width: 100%;
+  overflow: hidden;
+  border-radius: 0.75rem;
+  background: var(--cw-navy);
+}
+
+.mediaFrameWide {
+  aspect-ratio: 1200 / 630;
+}
+
+.mediaFrameSquare {
+  aspect-ratio: 1;
+}
+
+.mediaFrameWide img,
+.mediaFrameSquare img {
+  display: block;
+  width: 100%;
+  height: 100%;
+  object-fit: contain;
+}
+
+.checklist {
+  max-width: 92rem;
+  margin: 1rem auto 0;
+  padding: 1.1rem 1.25rem;
+}
+
+.checklist h2 {
+  margin-top: 0;
+}
+
+.checklist ul {
+  columns: 2;
+  margin-bottom: 0;
+  padding-left: 1.2rem;
+  gap: 2rem;
+}
+
+.checklist li {
+  break-inside: avoid;
+  margin-bottom: 0.6rem;
+}
+
+@media (max-width: 760px) {
+  .page {
+    padding: 0.6rem;
+  }
+
+  .header {
+    display: grid;
+    padding: 1rem;
+    border-radius: 0.85rem;
+  }
+
+  .pending {
+    justify-self: start;
+  }
+
+  .grid {
+    grid-template-columns: minmax(0, 1fr);
+    gap: 0.75rem;
+  }
+
+  .card,
+  .checklist {
+    border-radius: 0.85rem;
+  }
+
+  .cardHead {
+    align-items: flex-start;
+    padding: 0.75rem 0.8rem;
+  }
+
+  .lockupStageLight,
+  .lockupStageDark {
+    aspect-ratio: 16 / 7;
+    min-height: 0;
+    padding: 0.75rem;
+  }
+
+  .markGrid {
+    grid-template-columns: repeat(3, minmax(0, 1fr));
+    padding: 0.75rem;
+    gap: 0.55rem;
+  }
+
+  .appGrid {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+  }
+
+  .microRow {
+    grid-template-columns: 3.4rem 4rem minmax(0, 1fr);
+  }
+
+  .zoomBox {
+    width: min(7rem, 28vw);
+    height: min(7rem, 28vw);
+  }
+
+  .zoomBox img {
+    width: 85%;
+    height: 85%;
+  }
+
+  .socialGrid {
+    grid-template-columns: minmax(0, 1fr);
+    padding: 0.75rem;
+  }
+
+  .wide {
+    grid-column: auto;
+  }
+
+  .checklist {
+    padding: 1rem;
+  }
+
+  .checklist ul {
+    columns: 1;
+  }
+}

