+                  {seekPreview.image ? (
+                    <>
+                      {/* eslint-disable-next-line @next/next/no-img-element */}
+                      <img
+                      src={seekPreview.image}
+                        alt=""
+                      />
+                    </>
+                  ) : (
+                    <span className="player-seek-preview-placeholder" />
+                  )}
+                </div>
+
+                <span className="player-seek-preview-time">
+                  {formatTime(seekPreview.time)}
+                </span>
+              </div>
+            ) : null}
+
+            <input
+              className="player-seek"
+              type="range"
+              min={0}
+              max={seekMaximum}
+              step={0.1}
+              value={seekValue}
+              disabled={duration <= 0}
+              aria-label="Seek"
+              onPointerDown={(event) => {
+                event.stopPropagation();
+                beginTimelineScrub(
+                  Number(event.currentTarget.value),
+                );
+              }}
+              onPointerUp={() => {
+                endTimelineScrub();
+              }}
+              onPointerCancel={() => {
+                endTimelineScrub();
+              }}
+              onBlur={() => {
+                if (timelineScrubbingRef.current) {
+                  endTimelineScrub();
+                }
+              }}
+              onChange={(event) => {
+                const value = Number(
+                  event.currentTarget.value,
+                );
+
+                if (timelineScrubbingRef.current) {
+                  updateTimelineScrub(value);
+                } else {
+                  handleSeek(value);
+                }
+              }}
+            />
+          </div>
+
+          <div className="player-time-row">
+            <span>
+              {formatTime(currentTime)}
+            </span>
+
+            <span>
+              {formatTime(duration)}
+            </span>
+          </div>
+
+          <div className="player-control-row">
+            <div className="player-control-group">
+              <button
+                type="button"
+                className="player-control-button"
+                aria-label={
+                  isPlaying
+                    ? "Pause"
+                    : "Play"
+                }
+                onClick={() =>
+                  void togglePlayback()
+                }
+              >
+                {isPlaying ? <PauseIcon /> : <PlayIcon />}
+              </button>
+
+              <button
+                type="button"
+                className="player-control-button player-skip-button"
+                aria-label="Back 10 seconds"
+                onClick={() => {
+                  seekBy(-10);
+                  revealControls();
+                }}
+              >
+                <SkipBackIcon />
+              </button>
+
+              <button
+                type="button"
+                className="player-control-button player-skip-button"
+                aria-label="Forward 10 seconds"
+                onClick={() => {
+                  seekBy(10);
+                  revealControls();
+                }}
+              >
+                <SkipForwardIcon />
+              </button>
+
+              <button
+                type="button"
+                className="player-control-button"
+                aria-label={
+                  isMuted
+                    ? "Unmute"
+                    : "Mute"
+                }
+                onClick={toggleMute}
+              >
+                <VolumeIcon muted={isMuted} />
+              </button>
+
+              <input
+                className="player-volume"
+                type="range"
+                min={0}
+                max={1}
+                step={0.05}
+                value={
+                  isMuted
+                    ? 0
+                    : volume
+                }
+                aria-label="Volume"
+                onChange={(event) => {
+                  handleVolume(
+                    Number(
+                      event.currentTarget
+                        .value,
+                    ),
+                  );
+                }}
+              />
+            </div>
+
+            <div className="player-control-group player-control-group-right">
+              {playable.capabilities
+                .subtitles &&
+              playable.subtitles.length >
+                0 ? (
+                <select
+                  className="player-select"
+                  aria-label="Subtitles"
+                  value={
+                    selectedSubtitle
+                  }
+                  onChange={(event) => {
+                    applySubtitleSelection(
+                      event.currentTarget
+                        .value,
+                    );
+
+                    revealControls();
+                  }}
+                >
+                  <option value="off">
+                    CC Off
+                  </option>
+
+                  {playable.subtitles.map(
+                    (subtitle) => (
+                      <option
+                        key={subtitle.id}
+                        value={subtitle.id}
+                      >
+                        {subtitle.label}
+                      </option>
+                    ),
+                  )}
+                </select>
+              ) : null}
+
+              {playable.capabilities
+                .playbackSpeed ? (
+                <select
+                  className="player-select player-speed"
+                  aria-label="Playback speed"
+                  value={playbackRate}
+                  onChange={(event) => {
+                    changePlaybackRate(
+                      Number(
+                        event
+                          .currentTarget
+                          .value,
+                      ),
+                    );
+                  }}
+                >
+                  <option value={0.5}>
+                    0.5×
+                  </option>
+
+                  <option value={0.75}>
+                    0.75×
+                  </option>
+
+                  <option value={1}>
+                    1×
+                  </option>
+
+                  <option value={1.25}>
+                    1.25×
+                  </option>
+
+                  <option value={1.5}>
+                    1.5×
+                  </option>
+
+                  <option value={2}>
+                    2×
+                  </option>
+                </select>
+              ) : null}
+
+              <button
+                type="button"
+                className={[
+                  "player-control-button",
+                  castState === "connected"
+                    ? "player-cast-button--active"
+                    : "",
+                ].join(" ")}
+                aria-label={
+                  castState === "connected"
+                    ? "Casting"
+                    : "Cast"
+                }
+                aria-pressed={
+                  castState === "connected"
+                }
+                onClick={() => {
+                  revealControls();
+                  void requestCast();
+                }}
+              >
+                <CastIcon />
+              </button>
+
+              {playable.capabilities
+                .pictureInPicture ? (
+                <button
+                  type="button"
+                  className="player-control-button"
+                  aria-label="Picture-in-Picture"
+                  onClick={() => {
+                    revealControls();
+
+                    void togglePictureInPicture();
+                  }}
+                >
+                  <PiPIcon />
+                </button>
+              ) : null}
+
+              <button
+                type="button"
+                className="player-control-button"
+                aria-label="Fullscreen"
+                onClick={() => {
+                  revealControls();
+
+                  void toggleFullscreen();
+                }}
+              >
+                <FullscreenIcon />
+              </button>
+            </div>
+          </div>
+        </div>
+      </div>
+
+
+    </section>
+  );
+}

