diff --git a/infra/cloudflare/media-gateway.mjs b/infra/cloudflare/media-gateway.mjs
new file mode 100644
index 0000000..67cedee
--- /dev/null
+++ b/infra/cloudflare/media-gateway.mjs
@@ -0,0 +1,59 @@
+import ORIGINALS from './registry.mjs';
+import RENDITIONS from './renditions.mjs';
+export const AUD='97145b7d1ff85af6e9b355598eb35975bd48a10e1a6c04944b6fd7d647bc31f0';
+const OWNER='cinewatchtv.stream@gmail.com';
+const SITE='https://www.cinewatchtv.com';
+const HEADERS={'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Cross-Origin-Resource-Policy':'same-origin'};
+export function sourceFor(id,quality,derivatives={}) {
+ const original=ORIGINALS[id];
+ if(!original?.available)return null;
+ if(quality==='original')return original;
+ const d=derivatives[id];
+ if(quality!=='240p'||!d||d.parent_sha256!==original.sha256||d.height!==240||!Number.isSafeInteger(d.bytes)||d.bytes<=0||!/^[0-9a-f]{64}$/.test(d.sha256)||d.key!==`simulated-rights/bonanza/derived/${id}/240p/${d.sha256}.mp4`)return null;
+ return d;
+}
+export function parseRange(value,size) {
+ const m=/^bytes=(\d*)-(\d*)$/.exec(value);
+ if(!m||(!m[1]&&!m[2]))throw Error('Invalid range');
+ let start,end;
+ if(!m[1]){const suffix=Number(m[2]);if(!Number.isSafeInteger(suffix)||suffix<=0)throw Error('Invalid suffix');start=Math.max(0,size-suffix);end=size-1;}
+ else {start=Number(m[1]);end=m[2]?Number(m[2]):size-1;}
+ if(!Number.isSafeInteger(start)||!Number.isSafeInteger(end)||start<0||start>=size||end<start)throw Error('Unsatisfied range');
+ end=Math.min(end,size-1);return {offset:start,length:end-start+1};
+}
+function deny(status=403){return new Response('Playback unavailable',{status,headers:HEADERS});}
+export default {async fetch(request,env,ctx){
+ try{
+  if(!ctx.access||ctx.access.aud!==AUD)return deny();
+  const identity=await ctx.access.getIdentity();
+  if(identity?.email!==OWNER)return deny();
+  const url=new URL(request.url);
+  if(!['GET','HEAD'].includes(request.method))return deny(405);
+  if(url.pathname==='/identity')return Response.json({email:OWNER,authorized:true},{headers:HEADERS});
+  if(url.pathname==='/authorize'){
+   const state=url.searchParams.get('state');
+   const cookie=/(?:^|;\s*)CF_Authorization=([^;]+)/.exec(request.headers.get('Cookie')||'');
+   const jwt=request.headers.get('Cf-Access-Jwt-Assertion')||cookie?.[1];
+   if(!/^[0-9a-f]{64}$/.test(state||'')||!jwt||jwt.length>12000||! /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(jwt))return deny(400);
+   // Fragment is never sent to the CineWatch server/logs; nonce-bound session exchange follows.
+   return new Response(null,{status:303,headers:{...HEADERS,Location:SITE+'/stream-now/authorize#'+new URLSearchParams({token:jwt,state}).toString()}});
+  }
+  const match=/^\/media\/(S02E\d{2}|S02_CLIP\d{2})\/(original|240p)$/.exec(url.pathname);
+  if(!match||!env.MEDIA)return deny(404);
+  const variants=RENDITIONS;
+  const item=sourceFor(match[1],match[2],variants);if(!item)return deny(403);
+  const head=await env.MEDIA.head(item.key);
+  if(!head||head.size!==item.bytes||head.customMetadata?.sha256!==item.sha256)return deny(503);
+  const headers=new Headers({...HEADERS,'Content-Type':'video/mp4','Accept-Ranges':'bytes'});
+  let range;
+  if(request.headers.has('Range')){
+   try{range=parseRange(request.headers.get('Range'),item.bytes);}catch{headers.set('Content-Range',`bytes */${item.bytes}`);return new Response(null,{status:416,headers});}
+   headers.set('Content-Range',`bytes ${range.offset}-${range.offset+range.length-1}/${item.bytes}`);
+  }
+  headers.set('Content-Length',String(range?.length??item.bytes));
+  if(request.method==='HEAD')return new Response(null,{status:range?206:200,headers});
+  const object=await env.MEDIA.get(item.key,range?{range}:undefined);
+  if(!object?.body)return deny(503);
+  return new Response(object.body,{status:range?206:200,headers});
+ }catch{return deny(503);}
+}};

diff --git a/tests/watch/gateway.test.mjs b/tests/watch/gateway.test.mjs
new file mode 100644
index 0000000..cbc891a
--- /dev/null
+++ b/tests/watch/gateway.test.mjs
@@ -0,0 +1,24 @@
+import assert from 'node:assert/strict';
+import { test } from 'node:test';
+let mod; try {mod=await import('../../infra/cloudflare/media-gateway.mjs');}catch{}
+const get=()=>{assert.ok(mod,'Private media gateway not implemented');return mod;};
+test('missing Access cannot serve media',async()=>{const m=get();assert.equal((await m.default.fetch(new Request('https://test/media/S02E01/original'),{},{})).status,403)});
+test('wrong identity cannot serve media',async()=>{const m=get();assert.equal((await m.default.fetch(new Request('https://test/media/S02E01/original'),{}, {access:{aud:m.AUD,getIdentity:async()=>({email:'other@example.com'})}})).status,403)});
+test('blocked final three cannot select an object',()=>{const m=get();for(const id of ['S02E15','S02E16','S02E17'])assert.equal(m.sourceFor(id,'original'),null)});
+test('invalid identifiers do not select an object',()=>{const m=get();for(const id of ['../S02E01','S01E01','S02E18','tmdb:1018'])assert.equal(m.sourceFor(id,'original'),null)});
+test('primary season promo is correctly identified',()=>{const m=get();assert.equal(m.sourceFor('S02_CLIP03','original').bytes,7945453)});
+test('valid closed and suffix range',()=>{const m=get();assert.deepEqual(m.parseRange('bytes=0-31',100),{offset:0,length:32});assert.deepEqual(m.parseRange('bytes=-10',100),{offset:90,length:10})});
+test('malformed multiple and unsatisfied ranges rejected',()=>{const m=get();for(const s of ['bytes=0-1,5-6','bytes=100-','bytes=3-1','bytes=-0','bytes=a-b'])assert.throws(()=>m.parseRange(s,100))});
+test('oversized end clamps to exact available length',()=>{const m=get();assert.deepEqual(m.parseRange('bytes=90-999',100),{offset:90,length:10})});
+
+const ownerContext=()=>({access:{aud:mod.AUD,getIdentity:async()=>({email:'cinewatchtv.stream@gmail.com'})}});
+function bucketFor(item){return {head:async key=>key===item.key?{size:item.bytes,customMetadata:{sha256:item.sha256}}:null,get:async(key,options)=>({body:new Uint8Array(options?.range?.length??32).fill(7)})};}
+test('owner receives exact partial-content headers and bytes',async()=>{const m=get(),item=m.sourceFor('S02_CLIP03','original');const response=await m.default.fetch(new Request('https://test/media/S02_CLIP03/original',{headers:{Range:'bytes=8-23'}}),{MEDIA:bucketFor(item)},ownerContext());assert.equal(response.status,206);assert.equal(response.headers.get('Content-Range'),`bytes 8-23/${item.bytes}`);assert.equal(response.headers.get('Content-Length'),'16');assert.equal((await response.arrayBuffer()).byteLength,16);assert.match(response.headers.get('Cache-Control'),/no-store/)});
+test('owner HEAD verifies source without fetching body',async()=>{const m=get(),item=m.sourceFor('S02_CLIP03','original');let fetched=false;const bucket=bucketFor(item);bucket.get=async()=>{fetched=true;throw Error('HEAD must not fetch')};const response=await m.default.fetch(new Request('https://test/media/S02_CLIP03/original',{method:'HEAD'}),{MEDIA:bucket},ownerContext());assert.equal(response.status,200);assert.equal(response.headers.get('Content-Length'),String(item.bytes));assert.equal(fetched,false)});
+test('mismatched storage hash fails closed',async()=>{const m=get(),item=m.sourceFor('S02_CLIP03','original');const bucket=bucketFor(item);bucket.head=async()=>({size:item.bytes,customMetadata:{sha256:'bad'}});assert.equal((await m.default.fetch(new Request('https://test/media/S02_CLIP03/original'),{MEDIA:bucket},ownerContext())).status,503)});
+test('unsatisfied owner range returns 416 without fetching',async()=>{const m=get(),item=m.sourceFor('S02_CLIP03','original');const response=await m.default.fetch(new Request('https://test/media/S02_CLIP03/original',{headers:{Range:`bytes=${item.bytes}-`}}),{MEDIA:bucketFor(item)},ownerContext());assert.equal(response.status,416);assert.equal(response.headers.get('Content-Range'),`bytes */${item.bytes}`)});
+test('forbidden episode stays denied even with authenticated owner',async()=>{const m=get();assert.equal((await m.default.fetch(new Request('https://test/media/S02E15/original'),{MEDIA:{}},ownerContext())).status,403)});
+test('derived quality requires matching parent, height, hash and immutable key',()=>{const m=get(),original=m.sourceFor('S02_CLIP03','original'),sha='a'.repeat(64);const valid={parent_sha256:original.sha256,height:240,bytes:10,sha256:sha,key:`simulated-rights/bonanza/derived/S02_CLIP03/240p/${sha}.mp4`};assert.deepEqual(m.sourceFor('S02_CLIP03','240p',{S02_CLIP03:valid}),valid);for(const patch of [{parent_sha256:'bad'},{height:480},{bytes:0},{sha256:'bad'},{key:'other.mp4'}])assert.equal(m.sourceFor('S02_CLIP03','240p',{S02_CLIP03:{...valid,...patch}}),null)});
+test('native owner identity response is fixed and never exposes the assertion',async()=>{const m=get();const response=await m.default.fetch(new Request('https://test/identity'),{},ownerContext());assert.equal(response.status,200);assert.deepEqual(await response.json(),{email:'cinewatchtv.stream@gmail.com',authorized:true});assert.match(response.headers.get('Cache-Control'),/no-store/)});
+test('authorize cannot redirect without exact nonce and assertion',async()=>{const m=get();for(const url of ['https://test/authorize','https://test/authorize?state=bad'])assert.equal((await m.default.fetch(new Request(url),{},ownerContext())).status,400)});
+test('native owner assertion is passed only in a nonce-bound fragment',async()=>{const m=get(),nonce='a'.repeat(64),jwt='e30.e30.ZmFrZQ';for(const headers of [{'Cf-Access-Jwt-Assertion':jwt},{Cookie:`CF_Authorization=${jwt}`}]){const response=await m.default.fetch(new Request(`https://test/authorize?state=${nonce}`,{headers}),{},ownerContext());assert.equal(response.status,303);const url=new URL(response.headers.get('Location'));assert.equal(url.origin,'https://www.cinewatchtv.com');assert.equal(url.search,'');assert.equal(new URLSearchParams(url.hash.slice(1)).get('state'),nonce);assert.equal(new URLSearchParams(url.hash.slice(1)).get('token'),jwt)}});

